// Aetherus plugin/marketplace contract. No dynamic import, network, payment, webhook, or entitlement grant.
export const PLUGIN_SCHEMAS = Object.freeze({ manifest: 'earthus.plugin-manifest.v1', review: 'earthus.plugin-review.v1', execution: 'earthus.plugin-execution.v1' });
export class PluginSandboxError extends Error { constructor(code) { super(code); this.name = 'PluginSandboxError'; this.code = code; } }
const fail=c=>{throw new PluginSandboxError(c)}, need=(v,c)=>{if(!v)fail(c)}, freeze=v=>{if(v&&typeof v==='object'&&!Object.isFrozen(v)){Object.values(v).forEach(freeze);Object.freeze(v)}return v}, id=(v,c)=>{const r=String(v||'').trim();need(/^[a-z0-9][a-z0-9._-]{0,79}$/.test(r),c);return r};
export function validatePluginManifest(manifest) { need(manifest?.schema===PLUGIN_SCHEMAS.manifest&&manifest.schemaVersion===1,'PLUGIN_SCHEMA_INVALID'); const capabilities=Array.isArray(manifest.capabilities)?manifest.capabilities:[]; need(capabilities.every(v=>['read:catalog','read:mission','render:panel'].includes(v)),'PLUGIN_CAPABILITY_DENIED'); need(manifest.resourceLimits?.maxMemoryMb>0&&manifest.resourceLimits.maxMemoryMb<=64,'PLUGIN_MEMORY_LIMIT_INVALID'); need(manifest.resourceLimits?.maxCpuMs>0&&manifest.resourceLimits.maxCpuMs<=1000,'PLUGIN_CPU_LIMIT_INVALID'); need(typeof manifest.signature==='string'&&/^[a-f0-9]{64}$/.test(manifest.signature),'PLUGIN_SIGNATURE_REQUIRED'); return freeze({schema:PLUGIN_SCHEMAS.manifest,schemaVersion:1,id:id(manifest.id,'PLUGIN_ID_REQUIRED'),version:id(manifest.version,'PLUGIN_VERSION_REQUIRED'),capabilities:[...capabilities],resourceLimits:{maxMemoryMb:manifest.resourceLimits.maxMemoryMb,maxCpuMs:manifest.resourceLimits.maxCpuMs},signature:manifest.signature,salesEnabled:false,webhookEnabled:false}); }
export function reviewPlugin(manifest,{reviewerId,decision,reason}={}) { const value=validatePluginManifest(manifest); need(id(reviewerId,'PLUGIN_REVIEWER_REQUIRED'), 'PLUGIN_REVIEWER_REQUIRED'); need(['APPROVED','REJECTED'].includes(decision),'PLUGIN_REVIEW_DECISION_REQUIRED'); return freeze({schema:PLUGIN_SCHEMAS.review,pluginId:value.id,version:value.version,decision,reason:String(reason||'').slice(0,500),entitlementGranted:false}); }
export function executePluginReadOnly(manifest,review,{inputBytes=0}={}) { const value=validatePluginManifest(manifest); need(review?.decision==='APPROVED'&&review.pluginId===value.id&&review.version===value.version,'PLUGIN_REVIEW_REQUIRED'); need(Number.isFinite(inputBytes)&&inputBytes>=0&&inputBytes<=1024*1024,'PLUGIN_INPUT_LIMIT_EXCEEDED'); return freeze({schema:PLUGIN_SCHEMAS.execution,pluginId:value.id,version:value.version,status:'SANDBOX_CONTRACT_ONLY',networkCalls:0,stateWrites:0,paymentActions:0,webhookActions:0,entitlementGranted:false}); }
